        var dstIdx = (y * width + x) * 4

        var pixel = heap[srcIdx]

        var r = ((pixel >> 11) & 0x1f) << 3
        var g = ((pixel >> 5) & 0x3f) << 2
        var b = (pixel & 0x1f) << 3

