    if (config.down) {
      map[config.down] = "DOWN"
    }
    if (config.left) {
      map[config.left] = "LEFT"
    }
    if (config.right) {
      map[config.right] = "RIGHT"
    }
    if (config.start) {
      map[config.start] = "START"
    }
    if (config.mode) {
      map[config.mode] = "MODE"
    }
    if (config.a) {
      map[config.a] = "A"
    }
    if (config.b) {
      map[config.b] = "B"
    }
    if (config.c) {
      map[config.c] = "C"
    }
    if (config.x) {
      map[config.x] = "X"
    }
